    """
def linear_search_recursive(array: Any, item: Any, index: Any = 0) -> object {
    if (len(array) <= index) {
        return index;
    }
    if (array[index] == item) {
        return index;
    } else {
        return linear_search_recursive(array, item, (index + 1));
    }
}

