"""
    since bertMaskedLM output "a,x,b,c,noise,noise", we truncate them
    """
def postprocess(preds: Any, src: Any) -> object {
    res = [];
    for i in range(len(src)) {
        res.append("".join(preds[i].split())[:(len(src[i]["input_ids"]) - 2)]);
    }
    return res;
}

"""
    return max value by deviation from 0

    :param lst iterable: list of values to find max in
    :returns: max value by deviation from 0
    """
def amax(lst: Any) -> object {
    return max([abs(x) for x in lst]);
}
